mapper.select:
SELECT m.id AS memberId, g.streak_days AS streak
  FROM player_growth g
  JOIN ums_member m ON m.id = g.member_id AND m.status = 1 AND m.del_flag = 0
  LEFT JOIN growth_winback_state s ON s.member_id = m.id
 WHERE g.streak_days >= #{minStreak}
   AND g.last_checkin_date >= #{yesterday} AND g.last_checkin_date < #{today}

 ORDER BY s.last_evaluated_at IS NOT NULL, s.last_evaluated_at, m.id
 LIMIT #{limit}

SELECT * FROM (
    SELECT m.id AS memberId,  AS lastActive, s.last_evaluated_at AS evaluatedAt
      FROM ums_member m
      LEFT JOIN player_growth g ON g.member_id = m.id
      LEFT JOIN growth_winback_state s ON s.member_id = m.id
     WHERE m.status = 1 AND m.del_flag = 0

) c
 WHERE c.lastActive < #{lapsedBefore} AND c.lastActive >= #{lapsedAfter}
 ORDER BY c.evaluatedAt IS NOT NULL, c.evaluatedAt, c.memberId
 LIMIT #{limit}

SELECT member_id AS memberId, opted_out AS optedOut, opted_out_at AS optedOutAt, last_sent_at AS lastSent,
       last_trigger AS lastTrigger, awaiting_return AS awaiting, ignored_count AS ignored, sent_total AS sentTotal
  FROM growth_winback_state WHERE member_id = #{memberId}

mapper.update:
UPDATE growth_winback_state
   SET last_sent_at = #{now}, last_trigger = #{trigger}, last_ref = #{ref}, awaiting_return = 1,
       sent_total = sent_total + 1, last_evaluated_at = #{now}, update_time = #{now}
 WHERE member_id = #{memberId} AND opted_out = 0 AND ignored_count < #{maxIgnored}
   AND (last_sent_at IS NULL OR last_sent_at < #{sentBefore})

mapper.select:
SELECT id, name, lat, lng, create_time AS createTime FROM roam_poi
 WHERE status = 1 AND create_time >= #{since}
 ORDER BY create_time DESC LIMIT #{limit}

SELECT r.invitee_member_id AS inviteeId, r.status, r.reason, r.create_time AS createTime, m.nickname
  FROM growth_invite_reward r
  LEFT JOIN ums_member m ON m.id = r.invitee_member_id
 WHERE r.inviter_member_id = #{inviterId}
 ORDER BY r.create_time DESC LIMIT #{limit}
